Lemma mb_es_snoc_inv' : forall es : list mbe, es = [] \/ exists P xl sl, es = P ++ [(xl, sl)].
Proof. intros es. destruct es as [|e es'] eqn:E; [left; reflexivity| right]. rewrite <- E. apply mb_es_snoc_inv. rewrite E. discriminate. Qed.

Definition PREP_STACK : Z := 240 + ROPNEW_STACK.   (* [comment removed for export] *)

(* [comment removed for export] *)
Definition mb_new_blocks (es : list mbe) (insz n : Z) (p : bptr) (x : Z) : list block :=
  if mb_need es insz n then [(p, x, mb_block_size (mb_grow es insz n))] else [].

Section SR.
  Variable H : hsr.
  Hypothesis HH : heap_sr_hyps H.

  Definition prep_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (s : PState) (LB : list block) (res b : Z) (es : list mbe) (insz n lo B : Z) (m : mem) (mo : Model) : config -> Prop :=
    fun c => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (errv' : word) (s' : PState) (p : bptr) (x : Z),
      cfg_ms c = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                    F (ret_pc ra) fc None m' (seg_rom usegs)
      /\ hs_KREL H s' (cfg_model c) /\ hs_MPRES H mo (cfg_model c)
      /\ mem_inv usegs m' /\ stk usegs m' lo (bv_unsigned sp)
      /\ rw_cells usegs m' (errno_addr tp) [C4 errv'] /\ hs_rauxv_ok H m' B
      /\ hs_RHEAP H s' (mb_new_blocks es insz n p x ++ LB) m'
      /\ (mb_need es insz n = true -> rblock_range x (mb_block_size (mb_grow es insz n)))
      /\ rw_cells usegs m' res (SrCells b (mb_mid_out b es insz x) (b + 8) (mb_outpos es insz) (mb_mid_outend es insz n))
      /\ MBmid m' b es insz n x
      /\ MBufOwn (mb_new_blocks es insz n p x ++ LB) (mb_put_es es insz n x)
      /\ xpres LB (bv_unsigned sp) ((res, res + 40) :: (b, b + 64) :: mb_elemsW es) m m'.

  Definition prep_stmt : Prop :=
    forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
           (F : bvmap 5 word) (fc : bv 32) (m : mem) (mo : Model)
           (s : PState) (LB : list block) (res b : Z) (es : list mbe) (insz n lo B : Z) (rj : list byte) (errv : word),
      a0 = wz res -> a1 = wz b -> a2 = wz n ->
      MBuf m b es insz -> MBufOwn LB es -> 1 <= n -> insz + n <= 2^30 ->
      rw_cells usegs m res [CB 40 rj] -> bv_unsigned sp <= res -> res + 40 <= b -> b + 64 <= B ->
      hs_RHEAP H s LB m -> hs_KREL H s mo ->
      (mb_need es insz n = true -> lb_bytes LB + mb_block_size (mb_grow es insz n) <= hs_LIVE_MAX H) ->
      (mb_need es insz n = true -> Z.of_nat (length LB) + 1 <= hs_LIVE_CNT_MAX H) ->
      hs_rauxv_ok H m B -> bv_unsigned sp <= B -> B <= 2^64 ->
      stk usegs m lo (bv_unsigned sp) -> hceil <= lo -> lo <= bv_unsigned sp - PREP_STACK -> bv_unsigned sp mod 16 = 0 ->
      bv_unsigned ra mod 2 = 0 ->
      rw_cells usegs m (errno_addr tp) [C4 errv] -> mem_inv usegs m -> tp = Z_to_bv 64 RATP ->
      res mod 8 = 0 ->                                   (* [comment removed for export] *)
      hs_SR H (prep_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc s LB res b es insz n lo B m mo)
        (mkCfg (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                   F (Z_to_bv 64 P_MB_PREPARE) fc None m (seg_rom usegs)) mo).

  (* [comment removed for export] *)
  Definition prep_end_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (res b : Z) (es : list mbe) (insz n x lo : Z) (W : list (Z * Z)) (m0 : mem) : machine_state -> Prop :=
    fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
      ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
               F (ret_pc ra) fc None m' (seg_rom usegs)
      /\ munch W m0 m' /\ wmono usegs m0 m' /\ mem_inv usegs m'
      /\ stk usegs m' lo (bv_unsigned sp)
      /\ rw_cells usegs m' res (SrCells b (mb_mid_out b es insz x) (b + 8) (mb_outpos es insz) (mb_mid_outend es insz n))
      /\ MBmid m' b es insz n x.

  (* [comment removed for export] *)
  Lemma prep_finish : forall (spq res b : Z) (es : list mbe) (insz n x lo : Z) (W : list (Z * Z)) (m0 m1 : mem) (rj : list byte)
      (gp tp s10 s11 s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v rav : word) (F : bvmap 5 word) fc ms1,
    prep_attail_post spq gp tp s10 s11 s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v rav F fc res b es insz n x lo W m0 ms1 ->
    mb_ok es insz -> 1 <= n -> insz + n <= 2^30 ->
    rw_cells usegs m0 res [CB 40 rj] -> disjoint_from W res 40 -> spq + 176 <= res -> res + 40 <= b ->
    lo + 16 <= spq -> hceil <= lo -> spq mod 8 = 0 -> spq + 176 < 2^64 -> bv_unsigned rav mod 2 = 0 ->
    res mod 8 = 0 ->
    (forall a, lo <= a < spq + 88 -> ~ outside W a) ->
